/**
 * Note editor (docs/14 Step 6).
 * - Synthetic clipboard samples as Word and Excel put them on the clipboard: styles, Office namespaces, conditional
 *   comments, col / colgroup, colspan, padding — sanitised to the MCA subset (the gate's HTML check passes), tables
 *   kept, Auto format dropping empty rows / columns / paragraphs without losing text.
 * - The live check: schema problems and the layout report; strings saved as plain text.
 * - Blocks of a converted document.
 * - The text-block hierarchy on C&I and Ind AS; golden: Dixon (DGPL, generated by webXBRL, accepted by MCA).
 */
import { existsSync, readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import {
  applyFactPatch,
  assembleAuthority,
  Authority,
  autoFormatNote,
  checkNote,
  documentBlocks,
  htmlGuidelineIssues,
  importXbrl,
  noteForEditor,
  noteStructureIssues,
  noteValue,
  parentTextBlock,
  Session,
} from '../src/index'

const KB = (f: string) => new URL(`../../knowledge_base/${f}`, import.meta.url)
const DIXON = new URL('../../data/Instance_Dixon_Global_Private_2025-26_001.xml', import.meta.url)
const json = (u: URL) => JSON.parse(readFileSync(u, 'utf8'))
const load = (kb: string) => new Authority(assembleAuthority(json(KB(`${kb}_engine_authority.json`)), json(KB(`${kb}_engine_rules.json`))))
const META = {
  name: 'Z Pvt Ltd', cin: 'U72200KA2010PTC123456', reportType: 'Standalone', level: 'Actual', statementPlaces: 2, displayPlaces: 2,
  periods: { cy: { start: '2025-04-01', end: '2026-03-31' }, py: { start: '2024-04-01', end: '2025-03-31' } },
}

/** what Word 365 puts on the clipboard for a heading, a paragraph, an empty line and a table with a merged row */
const WORD = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word">
<head><meta charset="utf-8"><style>p.MsoNormal{margin:0}</style><!--[if gte mso 9]><xml><o:OfficeDocumentSettings/></xml><![endif]--></head>
<body lang=EN-IN><!--StartFragment-->
<p class=MsoNormal style='margin-bottom:6pt'><b><span style='font-size:12pt;font-family:"Arial"'>Particulars of loans<o:p></o:p></span></b></p>
<p class=MsoNormal style='text-align:justify'><span style='font-family:"Arial"'>The company has not given any loan during the year.<o:p></o:p></span></p>
<p class=MsoNormal><o:p>&nbsp;</o:p></p>
<table class=MsoTableGrid border=1 cellspacing=0 cellpadding=0 style='border-collapse:collapse'>
 <colgroup><col width=200><col width=100><col width=100></colgroup>
 <tr style='height:12pt'><td width=200 valign=top style='border:solid windowtext 1pt'><p class=MsoNormal><b>Name</b></p></td>
  <td width=100 valign=top><p class=MsoNormal align=right style='text-align:right'>&nbsp;&nbsp;2026</p></td><td width=100><p class=MsoNormal>&nbsp;</p></td></tr>
 <tr><td><p class=MsoNormal>A Ltd</p></td><td><p class=MsoNormal align=right>&nbsp;&nbsp;&nbsp;1,250</p></td><td><p class=MsoNormal>&nbsp;</p></td></tr>
 <tr><td colspan=3><p class=MsoNormal>Loans are repayable on demand.</p></td></tr>
</table>
<!--EndFragment--></body></html>`

/** what Excel puts on the clipboard for a 3 × 3 range with an empty middle column */
const EXCEL = `<html xmlns:x="urn:schemas-microsoft-com:office:excel"><body><!--StartFragment-->
<table border=0 cellpadding=0 cellspacing=0 width=300 style='border-collapse:collapse;width:225pt'>
 <col width=150><col width=50><col width=100>
 <tr height=20><td height=20 class=xl65 width=150>Particulars</td><td class=xl65></td><td class=xl66 align=right width=100>2026</td></tr>
 <tr height=20><td height=20 class=xl67>Trade receivables</td><td></td><td class=xl68 align=right>&nbsp;12,345.00</td></tr>
 <tr height=20><td height=20></td><td></td><td></td></tr>
</table><!--EndFragment--></body></html>`

const tables = (html: string) => (html.match(/<table/g) ?? []).length
const rows = (html: string) => (html.match(/<tr/g) ?? []).length

describe('pasted Word / Excel content', () => {
  it('Word: the MCA subset only — no styles, Office tags or col — with the paragraphs and the table kept', () => {
    const value = noteValue(WORD, 'textBlock')
    expect(htmlGuidelineIssues(value)).toEqual([])
    expect(value).not.toMatch(/style=|<o:|<col|colspan|MsoNormal|<b>/)
    expect(value).toContain('The company has not given any loan during the year.')
    expect(value).toContain('Loans are repayable on demand.')
    expect(tables(value)).toBe(1)
    expect(checkNote(WORD)).toMatchObject({ renders: true, errors: [] })
  })

  it('Excel: the range becomes one MCA table; padding before numbers goes', () => {
    const value = noteValue(EXCEL, 'textBlock')
    expect(htmlGuidelineIssues(value)).toEqual([])
    expect(value).toContain('Trade receivables')
    expect(value).toMatch(/>12,345\.00</)
  })

  it('Auto format drops empty paragraphs, columns and rows and keeps every text', () => {
    const before = noteForEditor(noteValue(EXCEL, 'textBlock'))
    const { html, stats } = autoFormatNote(EXCEL)
    expect(stats.columns).toBe(1)
    expect(stats.rows).toBe(1)
    expect(rows(html)).toBe(rows(before) - 1)
    for (const text of ['Particulars', 'Trade receivables', '12,345.00', '2026']) expect(html).toContain(text)
    const word = autoFormatNote(WORD)
    expect(word.stats.blank).toBeGreaterThanOrEqual(1)
    expect(word.html).toContain('Loans are repayable on demand.')
    expect(checkNote(word.html).layout.blank).toBe(0)
  })

  it('the live check: what the schema rejects, and what prints untidily', () => {
    const bad = checkNote('<p>ok</p><img src="x">', 'textBlock')
    expect(bad.renders).toBe(true) // the image is dropped, not saved
    expect(checkNote('<p></p><p>Text</p><h1>Big</h1>').layout).toMatchObject({ blank: 1, largeHeadings: 1 })
    expect(checkNote('<p>A <b>bold</b> word</p>', 'string')).toMatchObject({ value: 'A bold word', errors: [] })
  })

  it('splits a converted document into blocks a notes view selects', () => {
    const blocks = documentBlocks('<h1>Directors report</h1><p>One.</p><p>Two.</p><table><tr><td>a</td><td>b</td></tr></table>')
    expect(blocks).toHaveLength(4)
    expect(blocks[3]).toMatch(/^<table/)
    expect(htmlGuidelineIssues(noteValue(blocks.slice(1, 3).join(''), 'textBlock'))).toEqual([])
  })
})

describe.each([
  ['ci', 'in-ca:DisclosureInAuditorsReportExplanatoryTextBlock'],
  ['ind_as', 'in-ca:DisclosureInAuditorsReportExplanatory'],
])('text-block hierarchy on %s', (kb, parent) => {
  const A = load(kb)
  const REMARKS = 'in-ca:AuditorsQualificationsReservationsOrAdverseRemarksInAuditorsReport'
  const session = () => {
    const S = new Session(A)
    S.setMeta(META)
    return S
  }
  const write = (S: Session, concept: string, value: string) => applyFactPatch(S, { op: 'setText', fact: { concept, scope: 'CY' }, value, source: { kind: 'user' } })

  it('finds the parent text block from the presentation; a table line item or a top text block has none of its own', () => {
    expect(parentTextBlock(A as never, REMARKS)).toBe(parent)
    expect(parentTextBlock(A as never, parent)).toBeNull()
  })

  it('reports a sub-item without its parent text block, once, until the parent is tagged', () => {
    const S = session()
    write(S, REMARKS, 'Qualified on inventory valuation.')
    expect(noteStructureIssues(S)).toMatchObject([{ severity: 'INFO', code: 'textblock.parent', concept: REMARKS, scope: 'CY' }])
    write(S, parent, '<p>Auditor’s report</p>')
    expect(noteStructureIssues(S)).toEqual([])
  })
})

describe.skipIf(!existsSync(DIXON))('text-block hierarchy on Dixon (DGPL, webXBRL, accepted by MCA)', () => {
  it('reports 14 sub-items without their parent text block (hints only: MCA accepted them)', () => {
    const A = load('ind_as')
    const S = new Session(A, importXbrl(A, readFileSync(DIXON, 'utf8'), { fileName: 'dixon.xml' }).filing as never)
    const issues = noteStructureIssues(S)
    expect(issues).toHaveLength(14)
    expect(new Set(issues.map((i) => i.concept)).size).toBe(14)
    expect(issues.every((i) => i.severity === 'INFO')).toBe(true)
  })
})
